        val memo = Array(rows) { IntArray(cols) }

        val dirs = arrayOf(intArrayOf(0, 1), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(-1, 0))

        for (i in 0 until rows) {
            for (j in 0 until cols) {
                maxDist = max(maxDist, dfs(matrix, i, j, memo, dirs))
            }
        }
        return maxDist
    }

    private fun dfs(matrix: Array<IntArray>, r: Int, c: Int, memo: Array<IntArray>, dirs: Array<IntArray>): Int {
        if (memo[r][c] != 0) {
            return memo[r][c]
        }

        var res = 1
        for (dir in dirs) {
            val newRow = r + dir[0]
            val newCol = c + dir[1]
            if (newRow >= 0 && newRow < matrix.size && newCol >= 0 && newCol < matrix[0].size
                && matrix[newRow][newCol] > matrix[r][c]) {
                res = max(res, 1 + dfs(matrix, newRow, newCol, memo, dirs))
            }
        }
        memo[r][c] = res
        return res
    }
}

