class Solution {
    /**
     * @param {number[][]} matrix
     * @return {number}
     */
    longestIncreasingPath(matrix) {
        if (matrix.length === 0) {
            return 0;
        }
        const rows = matrix.length;
        const cols = matrix[0].length;

        let maxDist = 0;
        const memo = Array.from({ length: rows }, () => Array(cols).fill(0));

        const dirs = [
            [0, 1],
            [1, 0],
            [0, -1],
            [-1, 0],
        ];

        /**
         * @param {number} r
         * @param {number} c
         * @param {number} prevVal
         * @return {number}
         */
        function dfs(r, c, prevVal) {
            if (
                r < 0 ||
                r === rows ||
                c < 0 ||
                c === cols ||
                matrix[r][c] <= prevVal
            ) {
                return 0;
            }
            if (memo[r][c] !== 0) {
                return memo[r][c];
            }

            let res = 1;
            for (const dir of dirs) {
                const newRow = r + dir[0];
                const newCol = c + dir[1];
                if (
                    newRow >= 0 &&
                    newRow < rows &&
                    newCol >= 0 &&
                    newCol < cols &&
                    matrix[newRow][newCol] > matrix[r][c]
                ) {
                    res = Math.max(res, 1 + dfs(newRow, newCol, matrix[r][c]));
                }
            }
            memo[r][c] = res;
            return res;
        }

        for (let i = 0; i < rows; ++i) {
            for (let j = 0; j < cols; ++j) {
                maxDist = Math.max(maxDist, dfs(i, j, -1));
            }
        }
        return maxDist;
    }
}

